export function dashboard() {return new Response(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mini Hosting Cluster • Control</title><style>
:root{color-scheme:dark;font:16px system-ui,sans-serif}body{background:#0c1321;color:#e5e7eb;max-width:960px;margin:auto;padding:18px}h1{font-size:1.45rem}h2{font-size:1.05rem}main{display:grid;gap:16px}section{background:#18243a;border:1px solid #2f4260;border-radius:15px;padding:16px}label{display:block;margin:12px 0 4px;color:#bcc6d4;font-size:.87rem}input,select,button{font:inherit;border:1px solid #52617b;border-radius:8px;padding:10px;background:#101d31;color:white}input,select{box-sizing:border-box;width:100%}button{cursor:pointer;background:#2d59a1}button:disabled{opacity:.5;cursor:default}.warning{color:#fed7aa}.ok{color:#86efac}.fail{color:#fca5a5}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}small{color:#aebbd0}.actions{display:grid;gap:8px;grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #31425e;text-align:left;font-size:.85rem}</style></head>
<body><h1>Mini Hosting Cluster</h1><p>Chọn máy chính • Thủ công / Tự động • Fencing</p><main>
<section><label for="token">Admin token (chỉ trong bộ nhớ tab này)</label><input id="token" type="password" autocomplete="off" placeholder="Nhập MHC_ADMIN_TOKEN"><p><button id="refresh">Làm mới trạng thái</button> <small id="message"></small></p><div id="overview"></div><div id="nodes"></div></section>
<section><h2>Điều khiển</h2><p class="warning">Tự động chỉ an toàn khi có replication phù hợp. Snapshot không đủ để bảo đảm không mất dữ liệu.</p><label>Chế độ</label><select id="mode"><option value="manual">Thủ công</option><option value="auto">Tự động (nếu đủ điều kiện an toàn)</option></select><label>Chiến lược tự động</label><select id="strategy"><option value="preferred">Ưu tiên máy đã chọn</option><option value="score">Tự chọn theo điểm tài nguyên/online</option></select><label>Mã máy (Node ID)</label><input id="node" placeholder="m51 hoặc node UUID"><div class="actions" style="margin-top:12px"><button data-action="mode">Đổi chế độ</button><button data-action="strategy">Đổi chiến lược</button><button data-action="prefer">Đặt máy ưu tiên</button><button data-action="handoff">Chuyển máy chính có kiểm soát</button><button data-action="rejoin">Xác nhận đồng bộ trở lại</button></div></section>
<section><h2>Kiểm soát rủi ro RPO</h2><p>Chế độ nghiêm ngặt mặc định KHÔNG tự promote bản snapshot khi máy chính offline. Chế độ chấp nhận RPO có thể mất những giao dịch chưa được nhân bản.</p><div class="actions"><button data-action="risky-on">Bật auto failover chấp nhận rủi ro</button><button data-action="risky-off">Tắt auto failover rủi ro</button></div></section>
</main><script type="module">
const el=x=>document.getElementById(x);let last=null;
async function api(endpoint,body){const r=await fetch(endpoint,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+el('token').value,'content-type':'application/json'},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||r.status);return data}
const showMsg=(s,bad=false)=>{el('message').textContent=s;el('message').className=bad?'fail':'ok'};
async function refresh(){try{const s=await api('/__mhc/api/status');last=s;el('mode').value=s.mode;el('strategy').value=s.strategy;el('overview').replaceChildren();const p=document.createElement('p');p.textContent='Máy chính: '+(s.current||'Chưa có')+' | Term: '+s.term+' | Lease: '+(s.leaseRemainingMs/1000).toFixed(1)+'s | Chờ fencing: '+(s.fenceRemainingMs/1000).toFixed(1)+'s';el('overview').append(p);const p2=document.createElement('p');p2.textContent='Ưu tiên: '+(s.preferred||'Chưa chọn')+' | Pending: '+(s.pending||'không')+' | Auto RPO: '+(s.allowRiskyAuto?'CHẤP NHẬN RỦI RO':'NGHIÊM NGẶT');el('overview').append(p2);const t=document.createElement('table');const h=t.insertRow();for(const x of ['Node ID','Online','Đủ điều kiện','GTID','Điểm','Snapshot']){const th=document.createElement('th');th.textContent=x;h.append(th)}for(const [id,n] of Object.entries(s.nodes)){const tr=t.insertRow();for(const x of [id,n.online?'Có':'Không',n.armed&&n.healthy?'Có':'Không',n.replicationReady?'Có':'Không',n.score,n.snapshot||'—']){const td=tr.insertCell();td.textContent=x}}el('nodes').replaceChildren(t);showMsg('Đã cập nhật')}catch(e){showMsg(e.message,true)}}
el('refresh').onclick=refresh;
for(const b of document.querySelectorAll('[data-action]'))b.onclick=async()=>{const action=b.dataset.action,id=el('node').value.trim();try{let cmd,params;
if(action==='mode'){cmd='mode';params={mode:el('mode').value}}
else if(action==='strategy'){cmd='strategy';params={strategy:el('strategy').value}}
else if(action==='prefer'){cmd='prefer';params={nodeId:id}}
else if(action==='handoff'){if(!confirm('Chỉ chuyển sau khi dữ liệu đích đã xác minh. Bạn đã đối chiếu GTID/snapshot và chấp nhận nguy cơ mất những thay đổi chưa đồng bộ?'))return;cmd='handoff';params={nodeId:id,confirm:'DATA_VERIFIED'}}
else if(action==='rejoin'){if(!confirm('Đã đồng bộ lại dữ liệu của máy này từ máy đang chính?'))return;cmd='confirm-rejoin';params={nodeId:id,confirm:'DATA_REJOIN_VERIFIED'}}
else if(action.startsWith('risky-')){if(!confirm('Auto failover với async GTID vẫn có thể MẤT DỮ LIỆU khi nguồn chết đột ngột. Cho phép?'))return;cmd='allow-risky-auto';params={enabled:action==='risky-on',confirm:'I_ACCEPT_POSSIBLE_DATA_LOSS'}}
await api('/__mhc/api/admin',{action:cmd,params});await refresh()}
catch(e){showMsg(e.message,true)}};
</script></body></html>`,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','content-security-policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; form-action 'none'; base-uri 'none'; frame-ancestors 'none';"}})}
